function validateSlots(slots,pageCount){return Array.isArray(slots)&&slots.length>=2&&slots.length<=16&&slots.every(s=>['owner','coordinator','deputy','manager'].includes(s.role)&&Number.isInteger(s.page)&&s.page>=0&&s.page<pageCount&&[s.x,s.y,s.width,s.height,s.stampY].every(Number.isFinite)&&s.x>=0&&s.y>=0&&s.width>0&&s.width<=250&&s.height>0&&s.height<=100&&s.x+s.width<=596&&s.y+s.height<=842&&s.stampY<=825)}
