function whatsappLink(phone,name,title,kind='employee'){const digits=String(phone||'').replace(/[\s()+-]/g,'');const number=/^05\d{8}$/.test(digits)?'966'+digits.slice(1):/^9665\d{8}$/.test(digits)?digits:null;if(!number)return null;const text='السلام عليكم أستاذ/ '+name+'\nلديكم تكليف بانتظار توقيعكم بعنوان: '+title+'\nيرجى الدخول إلى حسابكم والاطلاع على التكليف والتوقيع عليه بالرسم أو رفع صورة توقيعكم.\nرابط الدخول: https://bakr4039-byte.github.io/followup/'+(kind==='teacher'?'teacher.html':'employee.html');return 'https://wa.me/'+number+'?text='+encodeURIComponent(text)}
function notificationCandidates(versions,search=''){return versions.filter(d=>isLatestVersion(d,versions)&&d.status==='open'&&nextSigner(d)&&(d.title.includes(search)||d.ownerName.includes(search)))}
