function notificationState(d,uid,cache){const entry=cache.get(d.id);if(!entry||entry.state==='loading')return {state:'loading',events:[]};if(entry.state==='error')return {state:'error',events:[]};const events=confirmedEvents(d,uid,entry.events);return {state:events.length?'confirmed':'unconfirmed',events}}
function dashboardSummary(versions,cache=new Map()){const current=versions.filter(d=>d.status!=='uploading'&&isLatestVersion(d,versions)),pending=current.filter(d=>nextSigner(d));const byRole={owner:0,coordinator:0,deputy:0,manager:0};for(const d of pending)for(const uid of pendingSigners(d))byRole[roleFor(d,uid)]++;const notified=new Set();let yes=0,no=0,unknown=0;for(const d of current){for(const uid of d.order)if(notificationState(d,uid,cache).state==='confirmed')notified.add(uid)}for(const d of pending)for(const uid of pendingSigners(d)){const status=notificationState(d,uid,cache).state;if(status==='confirmed')yes++;else if(status==='unconfirmed')no++;else unknown++}return {current,total:current.length,people:new Set(current.map(d=>d.ownerUid)).size,pending:pending.length,archived:current.filter(d=>d.status==='archived').length,ready:current.filter(d=>d.status==='open'&&d.signedCount===d.order.length).length,yes,no,unknown,notifiedPeople:notified.size,byRole}}
function matchesDashboard(d,filter,versions,cache){if(!filter)return true;if(!isLatestVersion(d,versions))return false;if(filter==='latest')return true;if(filter==='pending')return !!nextSigner(d);if(filter==='ready')return d.status==='open'&&d.signedCount===d.order.length;if(filter==='archived')return d.status==='archived';if(filter.startsWith('role:'))return !!nextSigner(d)&&pendingSigners(d).some(uid=>roleFor(d,uid)===filter.slice(5));if(filter==='any_wa')return d.order.some(uid=>notificationState(d,uid,cache).state==='confirmed');const uid=nextSigner(d);if(!uid)return false;return pendingSigners(d).some(u=>notificationState(d,u,cache).state===(filter==='wa_yes'?'confirmed':'unconfirmed'))}

function recipientFor(item,directory){if(item.recipient?.kind==='teacher'){const r=item.recipient;if(!/^[A-Za-z0-9_-]{1,128}$/.test(r.uid||'')||!r.scheduleName||typeof r.scheduleName!=='string'||!item.name||item.name.length>150)throw Error('حساب المعلم غير صالح: '+item.name);return {uid:r.uid,name:item.name,title:'معلم',active:true,kind:'teacher',scheduleName:r.scheduleName};}const entry=directory[item.memberId];if(!entry?.active||!entry.uid||entry.name!==item.name)throw Error('لا يوجد حساب مطابق ومفعّل: '+item.name);return entry;}
