function isCurrent(d){return isLatestVersion(d,rows)}
function myUid(d){const ids=viewUids();return pendingSigners(d).find(uid=>ids.includes(uid))||ids.find(uid=>d.order.includes(uid))}
function personalCard(d,stage){const signed=signedIds(d).includes(myUid(d)),ready=d.status==='open'&&d.signedCount===d.order.length;const label=stage==='action'?'متاح توقيعك الآن':stage==='archived'?'مكتمل ومحفوظ':stage==='previous'?'نسخة سابقة — للرجوع فقط':ready?'اكتملت جميع التوقيعات — بانتظار حفظ PDF':signed?'وقّعت — بانتظار استكمال بقية الاعتمادات':'بانتظار استكمال الاعتمادات';return `<article class="as-card as-personal-card"><span class="as-pill ${stage==='action'?'as-warning':stage==='archived'?'as-success':'as-neutral'}">${esc(label)}</span><h4>${esc(d.title)}</h4><p>صاحب التكليف: ${esc(d.ownerName)}</p><p>${d.signedCount} / ${d.order.length} توقيعات${nextSigner(d)&&stage!=='previous'?' · بانتظار: '+pendingSigners(d).map(uid=>esc(d.targets[uid]?.name||'الاعتماد')).join('، '):''}</p><small>${stage==='archived'?'تاريخ الحفظ: '+esc(when(d.archivedAt)):'تاريخ التكليف: '+esc(when(d.createdAt))}</small><p><button data-as-open="${esc(d.id)}">${stage==='action'?'فتح التكليف للتوقيع':stage==='archived'?'فتح المحفوظ وPDF النهائي':'عرض التكليف ومراحل الاعتماد'}</button></p></article>`}
function paintPersonal(){const personalRows=coordinatorView?rows.filter(d=>d.ownerUid===coordinatorView.uid):rows;const q=RecordWorkflow.assignmentQueues(personalRows,viewUids(),isLatestVersion),search=$('asSearch').value.trim();const summary=$('asPersonalSummary');summary.hidden=false;summary.innerHTML='<p class="as-muted">يُحمّل السجل المحفوظ لحسابك في كل زيارة. ما يحتاج توقيعك يظهر أولًا، ثم غير المكتمل، ثم المكتمل والمحفوظ.</p><div class="as-personal-metrics"><div><strong>'+q.action.length+'</strong><span>بانتظار توقيعك الآن</span></div><div><strong>'+q.pending.length+'</strong><span>قيد الاستكمال</span></div><div><strong>'+q.archived.length+'</strong><span>مكتملة ومحفوظة</span></div></div>';$('asList').classList.add('as-personal-list');const titles={action:'1 · بانتظار توقيعك الآن',pending:'2 · قيد الاستكمال',archived:'3 · المكتملة والمحفوظة'};let count=0;const sections=['action','pending','archived'].filter(stage=>mode==='all'||mode==='mine'&&stage==='action'||mode==='open'&&stage==='pending'||mode==='archived'&&stage==='archived').map(stage=>{const list=q[stage].filter(d=>!search||d.title.includes(search)||d.ownerName.includes(search));count+=list.length;return '<section class="as-personal-section" data-personal-stage="'+stage+'"><h3>'+titles[stage]+' <small>('+list.length+')</small></h3><div class="as-grid">'+(list.map(d=>personalCard(d,stage)).join('')||'<p class="as-muted">لا توجد تكليفات في هذا القسم ضمن البحث.</p>')+'</div></section>'}).join('');const previous=(mode==='all'?q.previous:mode==='archived'?q.previous.filter(d=>d.status==='archived'):[]).filter(d=>!search||d.title.includes(search)||d.ownerName.includes(search));$('asList').innerHTML=sections+(previous.length?'<details class="as-history"><summary>السجل السابق والنسخ السابقة ('+previous.length+')</summary><div class="as-grid">'+previous.map(d=>personalCard(d,'previous')).join('')+'</div></details>':'');renderAdminDashboard([]);}
function paint(){$('asPersonalSummary').hidden=true;$('asList').classList.remove('as-personal-list');$('asList').hidden=false;$('asMyTurnFilter').hidden=!(personal||coordinatorView);$('asImport').hidden=!adminViewAllowed();$('asOpenFilter').textContent=personal||coordinatorView?'قيد الاستكمال':'قيد التوقيع';$('asArchivedFilter').textContent=personal||coordinatorView?'المحفوظة':'المكتملة';document.querySelectorAll('[data-as-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.asMode===mode)));if((personal||coordinatorView)&&actor){$('asNotifyPending').hidden=true;paintPersonal();return;}$('asNotifyPending').hidden=!adminViewAllowed();const search=$('asSearch').value.trim();const shown=rows.filter(d=>(mode==='all'||isCurrent(d)&&d.status===mode)&&(d.title.includes(search)||d.ownerName.includes(search))&&matchesDashboard(d,adminViewAllowed()?dashFilter:'',rows,notificationCache));$('asList').innerHTML=assignmentGroups(shown).map(group=>'<section class="as-person-group"><h3>'+esc(group.name)+' <small>('+group.items.length+' تكليف)</small></h3>'+group.items.map(d=>`<article class="as-card"><h4>${esc(d.title)}</h4><p>${!isCurrent(d)?'نسخة سابقة — للرجوع فقط · ':''}${d.signedCount} / ${d.order.length} توقيعات · ${d.status==='archived'?'مكتمل ومحفوظ':d.signedCount===d.order.length?'اكتملت التوقيعات — جارٍ حفظ PDF':'بانتظار '+esc(d.targets[nextSigner(d)]?.name||'الاعتماد')}</p><small>${esc(when(d.createdAt))}</small>${adminViewAllowed()&&nextSigner(d)?'<p>'+notifyBadge(d,nextSigner(d))+'</p>':''}<p><button data-as-open="${esc(d.id)}">${adminViewAllowed()?'متابعة التكليف':'فتح تكليفي والتوقيع'}</button>${adminViewAllowed()&&isCurrent(d)&&nextSigner(d)?` <button data-as-notify="${esc(d.id)}">إبلاغ عبر واتساب</button>`:''}</p></article>`).join('')+'</section>').join('')||'<p>لا توجد تكليفات مطابقة.</p>';document.querySelectorAll('[data-as-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.asMode===mode)));renderAdminDashboard(shown)}
$('asSearch').oninput=paint;document.querySelectorAll('[data-as-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.asMode;dashFilter='';closeDetail();paint()});$('asList').onclick=e=>{const b=e.target.closest('[data-as-open]');if(b)detail(b.dataset.asOpen);const n=e.target.closest('[data-as-notify]');if(n)notifyDialog(rows.filter(d=>d.id===n.dataset.asNotify))};
