async function overlayImage(pdf,d,receipts){const font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica);for(const slot of d.slots){const r=receipts[slot.uid];if(!r)continue;const page=pdf.getPage(slot.page),png=await pdf.embedPng(r.signatureImage),scale=Math.min(slot.width/png.width,slot.height/png.height),w=png.width*scale,h=png.height*scale;page.drawImage(png,{x:slot.x+(slot.width-w)/2,y:page.getHeight()-slot.y-(slot.height+h)/2,width:w,height:h});const date=r.signedAt?.toDate?r.signedAt.toDate():new Date();const text=new Intl.DateTimeFormat('en-GB',{dateStyle:'short',...(slot.dateOnly?{}:{timeStyle:'short'}),timeZone:'Asia/Riyadh'}).format(date)+(slot.dateOnly?'':' (UTC+3)')+(r.delegated?' - Manager delegate':'');const size=Math.min(6.5,slot.width/font.widthOfTextAtSize(text,6.5)*6.5);page.drawText(text,{x:slot.x,y:page.getHeight()-slot.stampY-size,size,font,color:PDFLib.rgb(.22,.35,.43)})}return pdf}
